"""
Parameter management for energy saving operations
"""
from typing import TYPE_CHECKING, Dict, Any, List, Optional, Tuple
from taf.ul.sbts.energy_saving.decorators.connection import with_connection

if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


def try_to_convert_to_int(value):
    """Try to convert value to int, return original if fails"""
    try:
        return int(value)
    except (ValueError, TypeError):
        return value


class ParameterManager:
    """Manager for parameter validation and updates"""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    def _get_params_for_dn(self, xml_scf, dist_name: str, params_cache: Dict) -> Optional[Dict]:
        """Get parameters for given distName with caching"""
        if dist_name not in params_cache:
            params_cache[dist_name] = self.context.scf_manager.get_params_from_managed_object(xml_scf, dist_name)
        return params_cache[dist_name]

    def _process_param(self, param_name: str, param_dict: Dict, xml_scf, params_cache: Dict) -> Optional[Tuple]:
        """Process single parameter and return change tuple if needed"""
        if "dist_name" not in param_dict:
            return None

        dist_name = param_dict["dist_name"]
        params = self._get_params_for_dn(xml_scf, dist_name, params_cache)
        if not params:
            return None

        param_value = params.get(param_name)
        wanted_value = param_dict["value"]() if callable(param_dict["value"]) else param_dict["value"]
        validation_values = param_dict.get("validation_values")

        if param_value is None:
            return (dist_name, param_name, param_value, wanted_value)

        if validation_values:
            if callable(validation_values):
                is_valid = validation_values(
                    try_to_convert_to_int(param_value),
                    try_to_convert_to_int(wanted_value))
            else:
                is_valid = param_value in validation_values

            if is_valid:
                return None

        if str(param_value).lower() != str(wanted_value).lower():
            return (dist_name, param_name, param_value, wanted_value)

        return None

    @with_connection
    def verify_and_update_parameters(self, xml_scf, params_dict: Dict, delta_id: int = 0, connection=None) -> List[str]:
        """Generic function to verify and update parameters for any managed object
        {
            "lbpsCSONCtlEnabled": {
                "value": True,
                "dist_name": nrpgrp_dn
            },
            "lbpsLastCellMinLoad": {
                "value": 20,
                "validation_values": operator.ge,
                "dist_name": nrpgrp_dn
            },
            "lbpsLastCellSOEnabled": {"value": True, "dist_name": nrpgrp_dn},
            "lbpsMaxLoad": {"value": 80, "validation_values": operator.ge, "dist_name": nrpgrp_dn},
            "lbpsMinLoad": {"value": 40, "validation_values": operator.ge, "dist_name": nrpgrp_dn},
            "lbpsPdcchLoadOffset": {"value": 4, "validation_values": operator.ge, "dist_name": nrpgrp_dn},
            "lbpsSOMethod": {"value": "cell switch off", "dist_name": nrpgrp_dn}
        }
        """
        params_to_change = []
        change_messages = []
        params_cache = {}

        # Process all parameters
        for param_name, param_dict in params_dict.items():
            change_tuple = self._process_param(param_name, param_dict, xml_scf, params_cache)
            if change_tuple:
                params_to_change.append(change_tuple)

        # Apply changes if any
        if params_to_change:
            with self.context.delta_manager.delta_context(delta_id, auto_commit=True,
                                                          connection_alias=connection) as delta:
                for dist_name, param_name, current_value, wanted_value in params_to_change:
                    change_msg = (
                        f"Changing '{param_name}' [{dist_name}] "
                        f"from [{current_value}] to [{wanted_value}]"
                    )
                    change_messages.append(change_msg)
                    self.context.delta_manager.append_parameter_update_to_delta(
                        dist_name, param_name, wanted_value, delta)

        return change_messages

    def validate_parameter_value(self, current_value: Any, wanted_value: Any, validation_func=None) -> bool:
        """Validate single parameter value"""
        if validation_func:
            if callable(validation_func):
                return validation_func(
                    try_to_convert_to_int(current_value),
                    try_to_convert_to_int(wanted_value))
            else:
                return current_value in validation_func
        return str(current_value).lower() == str(wanted_value).lower()

    def get_parameter_diff(self, xml_scf, dist_name: str, param_name: str, wanted_value: Any) -> Dict:
        """Get difference between current and wanted parameter value"""
        params = self.context.scf_manager.get_params_from_managed_object(xml_scf, dist_name)
        if params is None:
            return {"error": f"Object {dist_name} not found"}

        current_value = params.get(param_name)
        return {
            "dist_name": dist_name,
            "parameter": param_name,
            "current_value": current_value,
            "wanted_value": wanted_value,
            "needs_change": current_value != wanted_value
        }

    def get_all_parameter_diffs(self, xml_scf, params_dict: Dict) -> List[Dict]:
        """Get differences for all parameters in params_dict"""
        diffs = []
        for param_name, param_dict in params_dict.items():
            if "dist_name" in param_dict:
                dist_name = param_dict["dist_name"]
                wanted_value = param_dict["value"]() if callable(param_dict["value"]) else param_dict["value"]
                diff = self.get_parameter_diff(xml_scf, dist_name, param_name, wanted_value)
                diffs.append(diff)
        return diffs

    def __repr__(self):
        return f"ParameterManager(context={self.context.connection_alias})"
